/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}

import { z } from "zod";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import {
  archiveScopeSchema,
  isoTimestampSchema,
  issueIdSchema,
  labelIdSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const issueStatusSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
]);

export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

export const createIssueSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
  title: z.string().min(3, "give the issue a title").max(200),
  description: z.string().max(20_000).nullable().default(null),
  status: issueStatusSchema.default("backlog"),
  priority: issuePrioritySchema.default("none"),
  assigneeId: userIdSchema.nullable().default(null),
  parentId: issueIdSchema.nullable().default(null),
  estimate: z.number().int().min(0).max(100).nullable().default(null),
  dueAt: isoTimestampSchema.nullable().default(null),
  labelIds: z.array(labelIdSchema).max(20).default([]),
});

export const updateIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  title: z.string().min(3).max(200).optional(),
  description: z.string().max(20_000).nullable().optional(),
  priority: issuePrioritySchema.optional(),
  estimate: z.number().int().min(0).max(100).nullable().optional(),
  dueAt: isoTimestampSchema.nullable().optional(),
  labelIds: z.array(labelIdSchema).max(20).optional(),
});

export const changeIssueStatusSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  status: issueStatusSchema,
});

export const assignIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  assigneeId: userIdSchema.nullable(),
});

export const archiveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
});

export const issueFilterSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema.optional(),
    status: z.array(issueStatusSchema).optional(),
    priority: z.array(issuePrioritySchema).optional(),
    assigneeId: userIdSchema.nullable().optional(),
    authorId: userIdSchema.optional(),
    labelIds: z.array(labelIdSchema).optional(),
    query: z.string().max(200).optional(),
    dueBefore: isoTimestampSchema.optional(),
  })
  .extend(pageRequestSchema.shape)
  .extend(archiveScopeSchema.shape);

/** Board drag-and-drop payload: move one issue into a column at an index. */
export const moveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  toStatus: issueStatusSchema,
  toIndex: z.number().int().min(0),
});

const _statusParity: IssueStatus = "in_review" satisfies z.infer<
  typeof issueStatusSchema
>;
const _priorityParity: IssuePriority = "urgent" satisfies z.infer<
  typeof issuePrioritySchema
>;
void _statusParity;
void _priorityParity;

export type CreateIssueInput = z.infer<typeof createIssueSchema>;
export type UpdateIssueInput = z.infer<typeof updateIssueSchema>;
export type ChangeIssueStatusInput = z.infer<typeof changeIssueStatusSchema>;
export type AssignIssueInput = z.infer<typeof assignIssueSchema>;
export type IssueFilterInput = z.infer<typeof issueFilterSchema>;
export type MoveIssueInput = z.infer<typeof moveIssueSchema>;

