1	/**
2	 * Domain events published by the service layer.
3	 *
4	 * Services stay decoupled from notifications, search, the audit log and
5	 * webhooks by announcing facts on the bus. If an event stops firing — or fires
6	 * with the wrong payload — every one of those concerns silently stops working,
7	 * which is why the contract is pinned here rather than through its consumers.
8	 */
9	import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
10	
11	vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
12	
13	import { subscribe } from "@/lib/event-bus";
14	import * as commentService from "@/server/services/comment-service";
15	import * as issueService from "@/server/services/issue-service";
16	import * as projectService from "@/server/services/project-service";
17	import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
18	import type { Tenant } from "./_support/fixtures";
19	import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
20	
21	let cleanup: () => void;
22	let tenant: Tenant;
23	const detachers: Unsubscribe[] = [];
24	
25	/** Collects every payload delivered for one event type during a test. */
26	function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
27	  const seen: TaskflowEventMap[K][] = [];
28	  detachers.push(
29	    subscribe(type, (payload) => {
30	      seen.push(payload);
31	    }),
32	  );
33	  return seen;
34	}
35	
36	beforeAll(async () => {
37	  cleanup = await useTemporaryDatabase();
38	  tenant = await createTenant("events");
39	});
40	
41	afterEach(() => {
42	  while (detachers.length > 0) detachers.pop()?.();
43	});
44	
45	afterAll(() => {
46	  cleanup();
47	});
48	
49	describe("issue.created", () => {
50	  it("is emitted once per created issue, carrying the actor and the issue", async () => {
51	    const seen = capture("issue.created");
52	
53	    const issue = await issueService.createIssue(
54	      tenant.actors.member,
55	      issueInput(tenant.org.id, tenant.project.id, {
56	        title: "Emit me",
57	        assigneeId: tenant.userIds.admin,
58	      }),
59	    );
60	
61	    expect(seen).toHaveLength(1);
62	    expect(seen[0]).toMatchObject({
63	      orgId: tenant.org.id,
64	      actorId: tenant.userIds.member,
65	      issueId: issue.id,
66	      projectId: tenant.project.id,
67	      title: "Emit me",
68	      assigneeId: tenant.userIds.admin,
69	      priority: "none",
70	    });
71	    expect(seen[0]?.occurredAt).toEqual(expect.any(String));
72	  });
73	
74	  it("is not emitted when the create is rejected", async () => {
75	    const seen = capture("issue.created");
76	
77	    await expect(
78	      issueService.createIssue(
79	        tenant.actors.viewer,
80	        issueInput(tenant.org.id, tenant.project.id),
81	      ),
82	    ).rejects.toThrow();
83	
84	    expect(seen).toHaveLength(0);
85	  });
86	});
87	
88	describe("issue.status_changed", () => {
89	  it("carries both ends of the transition", async () => {
90	    const issue = await issueService.createIssue(
91	      tenant.actors.member,
92	      issueInput(tenant.org.id, tenant.project.id, { title: "Move me" }),
93	    );
94	
95	    const seen = capture("issue.status_changed");
96	    await issueService.changeIssueStatus(tenant.actors.member, {
97	      orgId: tenant.org.id,
98	      issueId: issue.id,
99	      status: "in_progress",
100	    });
101	
102	    expect(seen).toHaveLength(1);
103	    expect(seen[0]).toMatchObject({ from: "backlog", to: "in_progress" });
104	  });
105	
106	  it("stays silent when the status did not actually move", async () => {
107	    const issue = await issueService.createIssue(
108	      tenant.actors.member,
109	      issueInput(tenant.org.id, tenant.project.id, { title: "No-op move" }),
110	    );
111	
112	    const seen = capture("issue.status_changed");
113	    await issueService.changeIssueStatus(tenant.actors.member, {
114	      orgId: tenant.org.id,
115	      issueId: issue.id,
116	      status: "backlog",
117	    });
118	
119	    expect(seen).toHaveLength(0);
120	  });
121	});
122	
123	describe("issue.assigned", () => {
124	  it("reports the previous assignee alongside the new one", async () => {
125	    const issue = await issueService.createIssue(
126	      tenant.actors.member,
127	      issueInput(tenant.org.id, tenant.project.id, {
128	        title: "Reassign me",
129	        assigneeId: tenant.userIds.member,
130	      }),
131	    );
132	
133	    const seen = capture("issue.assigned");
134	    await issueService.assignIssue(tenant.actors.member, {
135	      orgId: tenant.org.id,
136	      issueId: issue.id,
137	      assigneeId: tenant.userIds.admin,
138	    });
139	
140	    expect(seen).toHaveLength(1);
141	    expect(seen[0]).toMatchObject({
142	      previousAssigneeId: tenant.userIds.member,
143	      assigneeId: tenant.userIds.admin,
144	    });
145	  });
146	
147	  it("falls back to issue.updated when the issue is un-assigned", async () => {
148	    const issue = await issueService.createIssue(
149	      tenant.actors.member,
150	      issueInput(tenant.org.id, tenant.project.id, {
151	        title: "Unassign me",
152	        assigneeId: tenant.userIds.admin,
153	      }),
154	    );
155	
156	    const assigned = capture("issue.assigned");
157	    const updated = capture("issue.updated");
158	
159	    await issueService.assignIssue(tenant.actors.member, {
160	      orgId: tenant.org.id,
161	      issueId: issue.id,
162	      assigneeId: null,
163	    });
164	
165	    expect(assigned).toHaveLength(0);
166	    expect(updated).toHaveLength(1);
167	    expect(updated[0]?.changedFields).toEqual(["assigneeId"]);
168	  });
169	});
170	
171	describe("comment.created", () => {
