53	  // subscribe() is registered for each ActivityAction-shaped event type.
54	  it("subscribes to every event that maps to an ActivityAction", () => {
55	    const before = subscriberCount("project.created");
56	    const off = registerActivityListeners();
57	
58	    // registerActivityListeners() is idempotent per call — each call attaches
59	    // its own listener set, so calling it a second time adds one more.
60	    expect(subscriberCount("project.created")).toBe(before + 1);
61	    expect(subscriberCount("issue.created")).toBeGreaterThanOrEqual(1);
62	    expect(subscriberCount("member.role_changed")).toBeGreaterThanOrEqual(1);
