88	    expect(page.items[0]).toMatchObject({
89	      orgId: tenant.org.id,
90	      action: "project.created",
91	      actorId: tenant.userIds.member,
92	      subjectKind: "project",
93	      subjectId: tenant.project.id,
94	    });
95	  });
96	
97	  // A second identical emit produces a second row — the log is append-only.
98	  it("appends rather than de-duplicates repeated events", async () => {
99	    const payload = {
100	      orgId: tenant.org.id,
101	      actorId: tenant.userIds.member,
102	      occurredAt: tenant.org.createdAt,
103	      projectId: tenant.project.id,
104	      name: "Repeat project",
105	      slug: "repeat-project",
106	    } as const;
107	
108	    const before = await listActivity(tenant.actors.member, {
109	      orgId: tenant.org.id,
110	      action: ["project.created"],
111	      limit: 100,
112	      cursor: null,
113	    });
114	
115	    await emit("project.created", payload);
116	    await emit("project.created", payload);
117	
118	    const after = await listActivity(tenant.actors.member, {
119	      orgId: tenant.org.id,
120	      action: ["project.created"],
121	      limit: 100,
122	      cursor: null,
123	    });
124	
125	    expect(after.total).toBe(before.total + 2);
126	  });
127	
128	  // A throwing repository must not fail the emit for sibling subscribers.
