/**
 * Clears the assignee on every live issue held by a removed member, one
 * `issue.unassigned` per issue with the remover as actor. Archived issues are
 * left untouched — there is nothing left to notify or hand off.
 */
async function unassignLiveIssues(actor: Actor, userId: UserId): Promise<void> {
  let cursor: string | null = null;

  for (;;) {
    const page = await issueRepo.listIssues({
      orgId: actor.orgId,
      assigneeId: userId,
      limit: UNASSIGN_SWEEP_LIMIT,
      cursor,
    });

    for (const issue of page.items) {
      const after = await issueRepo.setIssueAssignee(
        actor.orgId,
        issue.id,
        null,
      );
      await emit("issue.unassigned", {
        ...actorEnvelope(actor),
        issueId: after.id,
        projectId: after.projectId,
        previousAssigneeId: userId,
      });
    }

    if (page.nextCursor === null) break;
    cursor = page.nextCursor;
  }
}

