21	import type { UpdateNotificationPreferenceInput } from "@/schemas/notification";
22	import type { ActionResult } from "@/types/api";
23	import type { OrgId, UserId } from "@/types/common";
24	import type { FeatureFlagSnapshot } from "@/types/feature-flag";
25	import type {
26	  NotificationKind,
27	  NotificationPreference,
28	} from "@/types/notification";
29	import type { ReactElement } from "react";
30	
31	export type NotificationPreferencesFormProps = {
32	  orgId: OrgId;
33	  userId: UserId;
34	  preferences: readonly NotificationPreference[];
35	  flags: FeatureFlagSnapshot;
36	  onSubmit: (
37	    input: UpdateNotificationPreferenceInput,
38	  ) => Promise<ActionResult<NotificationPreference>>;
39	};
40	
41	const KIND_LABELS: Readonly<Record<NotificationKind, string>> = {
42	  issue_assigned: "Issue assigned to me",
43	  issue_status_changed: "Issue status changed",
44	  issue_due_soon: "Issue due soon",
45	  issue_overdue: "Issue overdue",
46	  comment_created: "New comment",
47	  comment_mention: "I was mentioned",
48	  member_invited: "Member invited",
49	  member_joined: "Member joined",
50	  project_archived: "Project archived",
51	  plan_limit_reached: "Plan limit reached",
52	  digest_ready: "Daily digest ready",
53	};
54	
55	export function NotificationPreferencesForm(
56	  props: NotificationPreferencesFormProps,
57	): ReactElement | null {
58	  const { orgId, userId, preferences, flags, onSubmit } = props;
59	  const { submit, pending } = useFormAction(onSubmit);
60	
61	  const digestOn =
62	    flags.digest_email === true ||
63	    isEnabled("digest_email", ANONYMOUS_FLAG_CONTEXT);
64	
65	  function update(
66	    preference: NotificationPreference,
67	    patch: Partial<
68	      Pick<NotificationPreference, "inApp" | "email" | "digestOnly">
69	    >,
70	  ): void {
71	    void submit({
72	      orgId,
73	      userId,
74	      kind: preference.kind,
75	      inApp: patch.inApp ?? preference.inApp,
76	      email: patch.email ?? preference.email,
77	      digestOnly: patch.digestOnly ?? preference.digestOnly,
78	    });
79	  }
80	
81	  return (
